\begin{definition}[$\ell$-local randomized permutation family]\label{def:local}
A \emph{randomized permutation} on $\{0,1\}^n$ is an algorithm $\mathcal{P}_n$ taking an input $v \in \{0,1\}^n$ and randomness $\mathsf{r}$, and returning $\mathcal{P}_n(v;\mathsf{r}) \in \{0,1\}^n$, such that for every fixed value of $\mathsf{r}$ the map $v \mapsto \mathcal{P}_n(v;\mathsf{r})$ is a permutation of $\{0,1\}^n$. Equivalently, sampling $\mathsf{r}$ uniformly makes $\mathcal{P}_n$ a distribution over permutations of $\{0,1\}^n$; we write $\mathcal{P}_n(v)$ for $\mathcal{P}_n(v;\mathsf{r})$ with $\mathsf{r}$ uniform.

For $\ell \in \mathbb{N}$, such a $\mathcal{P}_n$ is \emph{$\ell$-local} if for every value of $\mathsf{r}$ and every $j \in [n]$ there is a set $S \subseteq [n]$ with $|S| \le \ell$ such that the $j$-th output bit of $\mathcal{P}_n(\,\cdot\,;\mathsf{r})$ is a function of the input bits indexed by $S$ alone. A family $\mathcal{P} = \{\mathcal{P}_n\}_{n \in \mathbb{N}}$ is $\ell$-local if every $\mathcal{P}_n$ is $\ell$-local for the same constant $\ell$.
\end{definition}

\begin{definition}[Sequential composition]\label{def:comp}
For $T \in \mathbb{N}$ and a randomized permutation $\mathcal{P}_n$, the $T$-fold sequential composition $\mathcal{P}^{T}$ is the randomized permutation
\[
  \mathcal{P}^{T} \colon x \mapsto \bigl(\mathcal{P}_n(\,\cdot\,;\mathsf{r}_T) \circ \cdots \circ \mathcal{P}_n(\,\cdot\,;\mathsf{r}_1)\bigr)(x),
\]
where $\mathsf{r}_1,\dots,\mathsf{r}_T$ are independent and uniform. For a function $T = T(n)$ this defines a family $\{\mathcal{P}^{T(n)}\}_{n \in \mathbb{N}}$ of randomized permutations, again written $\mathcal{P}^{T}$.
\end{definition}

\begin{definition}[Negligibly far from $k(n)$-wise independence]\label{def:kwise}
A family $\mathcal{Q} = \{\mathcal{Q}_n\}_{n \in \mathbb{N}}$ of randomized permutations on $\{0,1\}^n$ is \emph{negligibly far from $k(n)$-wise independent} if there is a negligible $\varepsilon$ such that for every $n$ and every tuple of pairwise distinct inputs $(x^1,\dots,x^{k(n)}) \in (\{0,1\}^n)^{(k(n))}$,
\[
  d_{\mathrm{TV}}\bigl(\,(\mathcal{Q}_n(x^1),\dots,\mathcal{Q}_n(x^{k(n)})),\ U_{n,k(n)}\,\bigr) \;\le\; \varepsilon(n),
\]
where the $k(n)$ outputs are produced by one single sample of $\mathcal{Q}_n$, so that the tuple lies in $(\{0,1\}^n)^{(k(n))}$.
\end{definition}

\begin{definition}[Pseudorandom permutation]\label{def:prp}
A family $\mathcal{Q} = \{\mathcal{Q}_n\}_{n \in \mathbb{N}}$ of randomized permutations on $\{0,1\}^n$ is a \emph{pseudorandom permutation} if for every probabilistic oracle algorithm $D$ running in time polynomial in $n$,
\[
  \Bigl|\ \Pr\bigl[D^{\mathcal{Q}_n}(1^n) = 1\bigr] \;-\; \Pr\bigl[D^{\Pi}(1^n) = 1\bigr]\ \Bigr| \;=\; \mathrm{negl}(n),
\]
where in the first probability a single sample of $\mathcal{Q}_n$ is fixed and $D$ may query it on inputs of its choice, in the second $\Pi$ is a uniformly random permutation of $\{0,1\}^n$, and in both cases $D$ is given forward evaluation queries only.
\end{definition}
